import { Table, GenericColumn, ReferenceColumn, StringColumn } from '../../db'

export const sp_js_include = Table({
    allowWebServiceAccess: true,
    attributes: {
        synch_attachments: true,
        update_synch: true,
    },
    audit: true,
    display: 'display_name',
    extends: 'sys_metadata',
    label: 'JS Include',
    name: 'sp_js_include',
    schema: {
        url: GenericColumn({
            columnType: 'url',
            label: 'JS file URL',
            maxLength: 1024,
        }),
        sys_ui_script: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'UI script',
            referenceTable: 'sys_ui_script',
        }),
        source: StringColumn({
            default: 'local',
            choices: {
                url: {
                    label: 'URL',
                    sequence: 1,
                },
                local: {
                    label: 'UI Script',
                    sequence: 0,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Source',
        }),
        display_name: StringColumn({
            label: 'Display name',
            maxLength: 1024,
        }),
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
    },
})
